package pe.cruzroja.convocatorias.users.presentation; import jakarta.servlet.http.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.util.Map; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/auth") public class AuthController {public record LoginRequest(@Email @NotBlank String email,@NotBlank String password){} @PostMapping("/login") ResponseEntity<Map<String,String>> login(@Valid @RequestBody LoginRequest request,HttpServletRequest servlet){servlet.getSession(true).setAttribute("demoUser",request.email());return ResponseEntity.ok(Map.of("mensaje","Sesión iniciada","rol",request.email().contains("jefatura")?"JEFATURA":"VOLUNTARIO"));} @PostMapping("/logout") Map<String,String> logout(HttpServletRequest request){var s=request.getSession(false);if(s!=null)s.invalidate();return Map.of("mensaje","Sesión cerrada");} @GetMapping("/me") Map<String,String> me(HttpServletRequest request){var s=request.getSession(false);if(s==null||s.getAttribute("demoUser")==null)throw new IllegalStateException("No hay una sesión activa");return Map.of("email",s.getAttribute("demoUser").toString(),"rol","VOLUNTARIO");}}
